<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{report:string;result:any;companyName:string}>();
const emit=defineEmits(['account']);
const minor=(value:string)=>{const negative=String(value).startsWith('-');const [whole,fraction='']=String(value).replace('-','').split('.');return (Number(whole)*100+Number(fraction.padEnd(2,'0')))*(negative?-1:1);};
const format=(n:number)=>n===0?'—':(n<0?'(':'')+(Math.abs(n)/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+(n<0?')':'');
const types=computed(()=>props.report==='profit'?['Income','Expense']:['Asset','Liability','Equity']);
const groups=computed(()=>types.value.map(type=>({type,label:({Asset:'Assets',Liability:'Liabilities',Equity:'Equity',Income:'Income',Expense:'Expenses'} as Record<string,string>)[type],rows:props.result.rows.filter((r:any)=>r.root_type===type),total:props.result.rows.filter((r:any)=>r.root_type===type).reduce((n:number,r:any)=>n+minor(r.amount),0)+(type==='Equity'?minor(props.result.summary.accumulated_earnings):0)})));
</script>
<template><article class="ac-statement"><header class="ac-statement-title"><p>{{companyName}}</p><h3>{{report==='profit'?'Statement of Profit and Loss':'Statement of Financial Position'}}</h3><span>{{report==='profit'?'For the period '+result.from+' to '+result.to:'As at '+result.to}}</span><small>Presented in {{result.currency}} · Posted transactions</small></header><div class="ac-statement-column"><span>Account</span><span>{{result.currency}}</span></div><section v-for="group in groups" :key="group.type" class="ac-statement-group"><h4>{{group.label}}</h4><div v-for="row in group.rows" :key="row.account_id" class="ac-statement-line"><button type="button" @click="emit('account',row.account_id)"><code>{{row.code}}</code>{{row.name}}</button><span>{{format(minor(row.amount))}}</span></div><div v-if="group.type==='Equity'" class="ac-statement-line"><span>Accumulated earnings</span><span>{{format(minor(result.summary.accumulated_earnings))}}</span></div><div class="ac-statement-subtotal"><strong>Total {{group.label.toLowerCase()}}</strong><strong>{{format(group.total)}}</strong></div></section><footer><div v-if="report==='profit'" class="ac-statement-grand"><strong>Net profit / (loss)</strong><strong>{{format(minor(result.summary.profit))}}</strong></div><template v-else><div class="ac-statement-grand"><strong>Total liabilities and equity</strong><strong>{{format(minor(result.summary.liabilities)+minor(result.summary.equity)+minor(result.summary.accumulated_earnings))}}</strong></div><p :class="minor(result.summary.balance_difference)===0?'ac-success':'ac-danger'">{{minor(result.summary.balance_difference)===0?'Assets equal liabilities and equity':'Balance difference: '+format(minor(result.summary.balance_difference))}}</p></template><small>Negative amounts are shown in parentheses. A dash represents zero.</small></footer></article></template>
